import java.util.ArrayList;
import java.util.Scanner;

class Stack<T> {
    private ArrayList<T> items;
    public Stack() {
        items = new ArrayList<>();
    }
    public void push(T item) {
        items.add(item);
    }
    public T pop() {
        if (items.isEmpty()) {
            return null;
        }
        return items.remove(items.size() - 1);
    }
    public T peek() {
        if (items.isEmpty()) {
            return null;
        }
        return items.get(items.size() - 1);
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Stack<Integer> st = new Stack<>();
        for (int i = 0; i < n; i++) {
            String op = sc.next();
            if (op.equals("push")) {
                int x = sc.nextInt();
                st.push(x);
            } else if (op.equals("pop")) {
                Integer v = st.pop();
                if (v == null) {
                    System.out.println("Empty");
                } else {
                    System.out.println(v);
                }
            } else {
                Integer v = st.peek();
                if (v == null) {
                    System.out.println("Empty");
                } else {
                    System.out.println(v);
                }
            }
        }
    }
}

import java.util.Scanner;
import java.util.function.Supplier;

public class Main {
    public static <T> T produce(Supplier<T> factory) {
        return factory.get();
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String choice = sc.next();
        double x = sc.nextDouble();
        Supplier<Double> factory;
        String label;
        if (choice.equals("circle")) {
            label = "Circle area";
            factory = () -> Math.PI * x * x;
        } else if (choice.equals("square")) {
            label = "Square area";
            factory = () -> x * x;
        } else {
            label = "Cube volume";
            factory = () -> x * x * x;
        }
        double value = produce(factory);
        System.out.print(label + ": ");
        System.out.printf("%.2f%n", value);
    }
}

import java.util.Scanner;

public class Main {
    public static <T> void reverse(T[] arr) {
        int i = 0;
        int j = arr.length - 1;
        while (i < j) {
            T tmp = arr[i];
            arr[i] = arr[j];
            arr[j] = tmp;
            i++;
            j--;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String[] words = new String[n];
        for (int i = 0; i < n; i++) {
            words[i] = sc.next();
        }
        reverse(words);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            if (i > 0) {
                sb.append(" ");
            }
            sb.append(words[i]);
        }
        System.out.println(sb.toString());
    }
}

import java.util.Scanner;
import java.util.function.Function;
import java.util.function.Predicate;

interface BinOp {
    int combine(int a, int b);
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = sc.nextInt();
        }
        String mapOp = sc.next();
        String filterOp = sc.next();
        String reduceOp = sc.next();

        Function<Integer, Integer> mapper;
        if (mapOp.equals("double")) {
            mapper = x -> x * 2;
        } else if (mapOp.equals("square")) {
            mapper = x -> x * x;
        } else {
            mapper = x -> x;
        }

        Predicate<Integer> filter;
        if (filterOp.equals("even")) {
            filter = x -> x % 2 == 0;
        } else if (filterOp.equals("positive")) {
            filter = x -> x > 0;
        } else {
            filter = x -> true;
        }

        BinOp reducer;
        if (reduceOp.equals("sum")) {
            reducer = (a, b) -> a + b;
        } else if (reduceOp.equals("max")) {
            reducer = (a, b) -> a > b ? a : b;
        } else {
            reducer = (a, b) -> a < b ? a : b;
        }

        int state = 0;
        boolean first = true;
        for (int i = 0; i < n; i++) {
            int mapped = mapper.apply(arr[i]);
            if (!filter.test(mapped)) {
                continue;
            }
            if (first) {
                state = mapped;
                first = false;
            } else {
                state = reducer.combine(state, mapped);
            }
        }
        if (first) {
            System.out.println("Result: empty");
        } else {
            System.out.println("Result: " + state);
        }
    }
}

import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

class Parcel<T> {
    private T id;
    private int weight;
    public Parcel(T id, int weight) {
        this.id = id;
        this.weight = weight;
    }
    public T getId() {
        return id;
    }
    public int getWeight() {
        return weight;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String mode = sc.next();
        int n = sc.nextInt();
        Comparator<Parcel<String>> cmp;
        if (mode.equals("asc")) {
            cmp = (p1, p2) -> p1.getWeight() != p2.getWeight() ? p1.getWeight() - p2.getWeight() : p1.getId().compareTo(p2.getId());
        } else {
            cmp = (p1, p2) -> p1.getWeight() != p2.getWeight() ? p2.getWeight() - p1.getWeight() : p1.getId().compareTo(p2.getId());
        }
        PriorityQueue<Parcel<String>> pq = new PriorityQueue<>(cmp);
        for (int i = 0; i < n; i++) {
            String id = sc.next();
            int w = sc.nextInt();
            pq.add(new Parcel<>(id, w));
        }
        while (!pq.isEmpty()) {
            Parcel<String> p = pq.poll();
            System.out.println(p.getId() + " " + p.getWeight());
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.function.Consumer;

public class Main {
    public static String reverse(String s) {
        char[] chars = s.toCharArray();
        int i = 0;
        int j = chars.length - 1;
        while (i < j) {
            char tmp = chars[i];
            chars[i] = chars[j];
            chars[j] = tmp;
            i++;
            j--;
        }
        return new String(chars);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<String, Consumer<String>> handlers = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            String type = sc.next();
            if (type.equals("upper")) {
                handlers.put(name, s -> System.out.println("UPPER: " + s.toUpperCase()));
            } else if (type.equals("reverse")) {
                handlers.put(name, s -> System.out.println("REVERSE: " + reverse(s)));
            } else {
                handlers.put(name, s -> System.out.println("ECHO: " + s));
            }
        }
        int m = sc.nextInt();
        for (int i = 0; i < m; i++) {
            String name = sc.next();
            String message = sc.next();
            Consumer<String> handler = handlers.get(name);
            if (handler == null) {
                System.out.println("No handler for " + name);
            } else {
                handler.accept(message);
            }
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;
import java.util.function.Function;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Map<String, Function<Integer, String>> registry = new HashMap<>();
        for (int i = 0; i < n; i++) {
            String tag = sc.next();
            String kind = sc.next();
            if (kind.equals("plain")) {
                registry.put(tag, x -> "v=" + x);
            } else if (kind.equals("hex")) {
                registry.put(tag, x -> "0x" + Integer.toHexString(x));
            } else {
                registry.put(tag, x -> Integer.toBinaryString(x));
            }
        }
        int m = sc.nextInt();
        for (int i = 0; i < m; i++) {
            String tag = sc.next();
            int value = sc.nextInt();
            Function<Integer, String> serializer = registry.get(tag);
            if (serializer == null) {
                System.out.println("Unknown type");
            } else {
                System.out.println(serializer.apply(value));
            }
        }
    }
}
